  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  font-weight: 600;
}

.text-field__input {
  font: inherit;
  font-size: clamp(1rem, 0.95rem + 0.25vw, 1.125rem);
  color: var(--ink);
  background: var(--slide);
  border: 1px solid var(--muted);
  border-radius: 4px;
  padding: 0.6em 0.75em;
  min-height: 44px;
  box-sizing: border-box;
  width: 100%;
  transition: border-color 150ms ease;
}

.text-field__input::placeholder {
  color: var(--muted);
  opacity: 1;
}

.text-field__input:focus-visible {
  border-color: var(--myelin);
}

.text-field__input[aria-invalid="true"] {
  border-color: var(--cresyl);
  border-width: 2px;
  padding: calc(0.6em - 1px) calc(0.75em - 1px);
}

.text-field__error {
  margin: 0;
  color: var(--cresyl);
  font-size: clamp(0.8125rem, 0.78rem + 0.2vw, 0.9375rem);
  font-weight: 600;
}

:root[data-motion="reduce"] .text-field__input {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .text-field__input {
    transition: none;
  }
}
